export const encode=(_,v)=>typeof v==='number'?(Number.isNaN(v)?'n:NaN':v===Infinity?'n:+Infinity':v===-Infinity?'n:-Infinity':Object.is(v,-0)?'n:-0':v):v;
export const json=v=>JSON.stringify(v,encode);
const clone=v=>Array.isArray(v)?v.map(clone):v;
export function generate(d3){
 const geometries=[],add=(id,geometry,profile='ordinary-canonical-finite')=>geometries.push({id,geometry,profile,area:d3.geoArea(geometry),length:d3.geoLength(geometry)}),ring=[[-20,-10],[-20,20],[30,20],[30,-10],[-20,-10]],hole=[[-5,0],[10,0],[10,10],[-5,10],[-5,0]],line=[[0,0],[90,0],[90,45]],polygon=coordinates=>({type:'Polygon',coordinates}),lines=coordinates=>({type:'LineString',coordinates});
 add('null-empty',null);add('unknown-empty',{type:'Empty'},'native-unknown-geometry-type-ignored');add('sphere',{type:'Sphere'});add('point',{type:'Point',coordinates:[17,23]});add('multipoint',{type:'MultiPoint',coordinates:[[0,0],[180,90],[-180,-90]]});add('empty-multipoint',{type:'MultiPoint',coordinates:[]});
 add('line-normal',lines(line));add('line-empty',lines([]));add('line-singleton',lines([[3,4]]));add('line-duplicates',lines([[0,0],[0,0],[-0,0],[90,0],[90,0]]));add('line-antimeridian',lines([[170,30],[-170,30],[-160,-10]]));add('line-poles',lines([[0,90],[90,0],[0,-90]]));add('line-antipodal',lines([[0,0],[180,0],[-180,0]]));
 add('multiline',{type:'MultiLineString',coordinates:[line,[],[[170,0],[-170,0]]]});add('polygon-closed',polygon([ring]));add('polygon-reversed',polygon([ring.slice().reverse()]));add('polygon-with-hole',polygon([ring,hole]));add('polygon-hole-reversed',polygon([ring,hole.slice().reverse()]));add('polygon-all-reversed',polygon([ring.slice().reverse(),hole.slice().reverse()]));add('polygon-empty',polygon([]));add('polygon-empty-ring',polygon([[]]),'native-empty-ring-invalid-checked-polygon');add('polygon-duplicates',polygon([[[0,0],[0,0],[10,0],[0,10],[0,0],[0,0]]]));
 add('polygon-antimeridian',polygon([[[170,-20],[170,20],[-170,20],[-170,-20],[170,-20]]]));add('polygon-north-pole',polygon([[[-180,80],[-60,80],[60,80],[180,80],[-180,80]]]));add('polygon-south-pole',polygon([[[-180,-80],[180,-80],[60,-80],[-60,-80],[-180,-80]]]));
 add('polygon-selfintersection',polygon([[[-10,-10],[10,10],[-10,10],[10,-10],[-10,-10]]]),'native-algebraic-area-no-topology-repair');add('multipolygon',{type:'MultiPolygon',coordinates:[[ring],[clone(ring).map(([x,y])=>[x+70,y])]]});add('multipolygon-overlap',{type:'MultiPolygon',coordinates:[[ring],[ring]]},'native-algebraic-sum-not-union');add('empty-multipolygon',{type:'MultiPolygon',coordinates:[]});
 add('collection',{type:'GeometryCollection',geometries:[null,{type:'Point',coordinates:[0,0]},lines(line),polygon([ring,hole]),{type:'Sphere'}]});add('collection-empty',{type:'GeometryCollection',geometries:[]});add('feature',{type:'Feature',properties:{},geometry:polygon([ring])});add('feature-collection',{type:'FeatureCollection',features:[{type:'Feature',geometry:lines(line)},{type:'Feature',geometry:polygon([ring])}]});
 add('polygon-unclosed-native',polygon([ring.slice(0,-1)]),'native-invalid-unclosed-ring-still-drops-final-vertex');add('line-nan',lines([[0,0],[NaN,20]]),'native-nonfinite');add('line-infinity',lines([[0,0],[Infinity,20]]),'native-nonfinite');add('budget-100000-duplicates',lines(Array.from({length:100000},()=>[0,0])),'source-budget-exactly100000');
 const closure={closedPolygonLength:d3.geoLength(polygon([ring])),sameCoordinatesLineLength:d3.geoLength(lines(ring)),lineWithoutClosingVertexLength:d3.geoLength(lines(ring.slice(0,-1))),lastToFirstDistance:d3.geoDistance(ring.at(-2),ring[0]),nativePolygonStreamPoints:ring.length-1,reason:'Polygon stream drops final coordinate, geoLength polygonStart/end noop: no closing segment is added.'};
 const distances=[],pairs=[['same',[0,0],[0,0]],['signzero',[-0,0],[0,-0]],['quarter',[0,0],[90,0]],['antipodal',[0,0],[180,0]],['near-antipodal',[0,0],[180-1e-10,1e-10]],['dateline',[179.9,20],[-179.9,20]],['poles',[0,90],[180,-90]],['same-pole',[0,90],[120,90]],['tiny',[0,0],[1e-12,-1e-12]],['tiny-offset',[30,40],[30+1e-12,40+1e-12]],['subnormal',[0,0],[Number.MIN_VALUE,-Number.MIN_VALUE]],['wrap',[540,20],[-180,20]],['outside-latitude',[0,100],[0,80]],['nan',[NaN,0],[0,0]],['infinity',[Infinity,0],[0,0]]];
 for(const[id,a,b]of pairs)distances.push({id,a,b,native:d3.geoDistance(a,b),profile:[...a,...b].every(Number.isFinite)&&[a[1],b[1]].every(v=>Math.abs(v)<=90)?'ordinary-finite':'native-invalid-public-coordinate'});
 const circles=[];for(const center of [[0,0],[179,20],[-179,-20],[0,90],[0,-90]])for(const radius of [0,1,30,90,150,180])for(const precision of [2,7,90,360]){
  const geometry=d3.geoCircle().center(center).radius(radius).precision(precision)();circles.push({id:`circle-${circles.length}`,center,radius,precision,status:'executed-native',geometry,area:d3.geoArea(geometry),length:d3.geoLength(geometry),points:geometry.coordinates[0].length});}
 for(const[id,center,radius,precision]of [['nan-center',[NaN,0],30,7],['infinity-center',[Infinity,0],30,7],['nan-radius',[0,0],NaN,7],['infinity-radius',[0,0],Infinity,7],['nan-precision',[0,0],30,NaN],['infinity-precision',[0,0],30,Infinity],['precision-zero',[0,0],30,0],['precision-negative',[0,0],30,-2],['precision-source-budget',[0,0],30,.000001]]){
  if(precision<0||precision>0&&Number.isFinite(precision)&&360/precision+2>100000){circles.push({id,center,radius,precision,status:precision<0?'not-executed-negative-step-nontermination':'not-executed-estimated-point-budget-exceeds100000'});continue;}
  const geometry=d3.geoCircle().center(center).radius(radius).precision(precision)();circles.push({id,center,radius,precision,status:'executed-native-noncanonical',geometry,area:d3.geoArea(geometry),length:d3.geoLength(geometry),points:geometry.coordinates[0].length});
 }
 return {files:{'geometry.json':JSON.stringify({scope:'Original native spherical integrals; algebraic area, no union or topology repair',geometries,closure,notExecuted:[{id:'source-budget-over100000',status:'not-executed-proposed-public-budget',specification:{type:'LineString',repeatPoint:[0,0],count:100001}}]},encode,2)+'\n','geometry-values.csv':geometries.map(r=>[r.id,r.profile,r.area,r.length].map(json).join('|')).join('\n')+'\n','distance.json':JSON.stringify(distances,encode,2)+'\n','circle.json':JSON.stringify(circles,encode,2)+'\n','circle-values.csv':circles.map(r=>[r.id,r.center,r.radius,r.precision,r.status,r.points??null,r.area??null,r.length??null].map(json).join('|')).join('\n')+'\n'},counts:{geometries:geometries.length,distances:distances.length,circles:circles.length,circlesExecuted:circles.filter(r=>r.geometry).length,circlesSkipped:circles.filter(r=>!r.geometry).length,ordinaryFiniteComparisonTolerance:1e-12},closure};
}
